'use strict';
/**
 * R27. Validate observed charts generated from the PINNED reference repo and
 * its exact installed iztro version, then compare geometric placements with
 * Thiên Đồ. Geometry matching is NOT name/school/criterion equivalence.
 *
 * No synthetic fixture is ever treated as a real engine observation. The CLI
 * requires an observation file generated by the external source checkout.
 */
const fs=require('node:fs');
const path=require('node:path');
const Engine=require('../../packages/astrology-engine/src/tuvi.js');
const {SOURCE_COMMIT,SOURCE_STEMS,auditSourceDoubleJiekongCodeConcordance}=
 require('../../packages/interpretation/src/classical-source-void-vocabulary.cjs');
const {projectSourceFuxunPartner}=
 require('../../packages/interpretation/src/classical-source-fuxun-formula.cjs');
const {auditClassicalVoidPairGeometry}=
 require('../../packages/interpretation/src/classical-source-void-geometry.cjs');

const BRANCHES=Object.freeze(['Tý','Sửu','Dần','Mão','Thìn','Tỵ','Ngọ','Mùi','Thân','Dậu','Tuất','Hợi']);
const LABELS=Object.freeze(['旬空','副旬','截空','副截']);
const RAW_LABELS=Object.freeze(['旬空','截路','空亡']);
const PROBE_SCHEMA='thiendo-r27-source-iztro-observation-v1';
const CASE_SCHEMA='thiendo-r27-public-synthetic-case-matrix-v1';
const PINNED_IZTRO='2.6.1';
const DISCLAIMER='Nguồn generateChart sử dụng iztro@2.6.1 đã khóa, có vá chính/phụ. So khớp hình học với Tuần/Triệt Thiên Đồ không chứng minh tương đương sao, trường phái, ý nghĩa hay điều kiện cách cục.';
const samePair=(a,b)=>Array.isArray(a)&&Array.isArray(b)&&a.length===2&&b.length===2&&
 [...a].sort((x,y)=>x-y).every((x,i)=>x===[...b].sort((x,y)=>x-y)[i]);
function requireSingle(stars,name){
 const values=stars&&Object.prototype.hasOwnProperty.call(stars,name)?stars[name]:null;
 if(!Array.isArray(values)||values.length!==1||
    !Number.isInteger(values[0])||values[0]<0||values[0]>11)
  throw new Error('Required source or raw iztro star is absent, duplicated or invalid: '+name);
 return values[0];
}
function validateObservationShape(observation,fixture){
 if(!observation||observation.schema!==PROBE_SCHEMA||!observation.provenance||
    observation.provenance.sourceCommit!==SOURCE_COMMIT||
    observation.provenance.sourceRepository!=='Renhuai123/ziwei-doushu'||
    observation.provenance.iztroVersion!==PINNED_IZTRO||
    observation.provenance.syntheticCasesOnly!==true||
    !Array.isArray(observation.records)||
    !fixture||fixture.schema!==CASE_SCHEMA||!Array.isArray(fixture.cases)||
    observation.records.length!==fixture.cases.length||fixture.cases.length!==65)
  throw new Error('R27 probe provenance or case set is not pinned and complete');
 const ids=new Set(fixture.cases.map(x=>x.id)),records=new Set(observation.records.map(x=>x.id));
 if(ids.size!==fixture.cases.length||records.size!==observation.records.length||
    [...ids].some(id=>!records.has(id)))throw new Error('Missing, duplicate or substituted R27 cases');
}
function evaluate(observation,fixture){
 validateObservationShape(observation,fixture);
 const expected=new Map(fixture.cases.map(x=>[x.id,x]));
 const results=[],failures=[];
 for(const record of observation.records){
  const test=expected.get(record.id);
  const context={id:record.id,kind:record.kind,solarDate:record.solarDate,
   hour:record.hour,gender:record.gender};
  try{
   if(!test||record.solarDate!==test.date||record.gender!==test.gender||
      record.hour!==test.hour||record.kind!==test.kind||
      record.hourBranch!==Math.floor(((test.hour+1)%24)/2)||
      !Number.isInteger(record.lunarYearStemIndex)||
      record.lunarYearStemIndex<0||record.lunarYearStemIndex>9||
      !Number.isInteger(record.lunarYearBranchIndex)||
      record.lunarYearBranchIndex<0||record.lunarYearBranchIndex>11)
    throw new Error('Birth case or lunar year metadata does not match the pinned matrix');
   const stem=SOURCE_STEMS[record.lunarYearStemIndex];
   const source=record.sourceStars,raw=record.rawIztroStars;
   const position=Object.fromEntries(LABELS.map(name=>[name,requireSingle(source,name)]));
   const rawPosition=Object.fromEntries(RAW_LABELS.map(name=>[name,requireSingle(raw,name)]));
   const partner=projectSourceFuxunPartner(position['旬空']);
   if(!partner||partner.partnerBranchIndex!==position['副旬'])
    throw new Error('Reference 旬空 and 副旬 violate applySchoolFuxun');
   if(rawPosition['旬空']!==position['旬空'])
    throw new Error('Source 旬空 was moved after iztro placement');
   const double=auditSourceDoubleJiekongCodeConcordance(stem);
   if(!double?.sourceFormulaConcordant)
    throw new Error('Pinned source Jiekong table is inconsistent');
   const sourceJie=position['截空'],sourceFu=position['副截'];
   if(sourceJie!==double.formulaCodes[0]-1||sourceFu!==double.formulaCodes[1]-1)
    throw new Error('Source 截空 and 副截 do not match source school double formula');
   const isYin=(record.lunarYearStemIndex%2)===1;
   if(sourceJie!==(isYin?rawPosition['空亡']:rawPosition['截路'])||
      sourceFu!==(isYin?rawPosition['截路']:rawPosition['空亡']))
    throw new Error('Pinned source swapped legacy iztro 截路/空亡 incorrectly');
   const chart=Engine.calculate({date:test.date,hour:test.hour,minute:test.minute,
    calendar:'solar',gender:test.gender});
   const chartBefore=JSON.stringify(chart);
   const localYearStem=chart.yearCanChi.split(' ')[0];
   const localStemSame=stem===localYearStem;
   const tri=chart.obstructionMarkers?.find(v=>v.name==='Triệt');
   const tuan=chart.obstructionMarkers?.find(v=>v.name==='Tuần');
   const sourcePair=[sourceJie,sourceFu],sourceXunPair=[position['旬空'],position['副旬']];
   const trietGeometry=Array.isArray(tri?.branches)?samePair(tri.branches,sourcePair):null;
   const tuanGeometry=Array.isArray(tuan?.branches)?samePair(tuan.branches,sourceXunPair):null;
   const localGeometry=auditClassicalVoidPairGeometry(chart);
   if(JSON.stringify(chart)!==chartBefore)throw new Error('Thiên Đồ chart mutated by the auditor');
   results.push(Object.freeze({...context,status:'source-consistent',sourceYearStem:stem,
    localYearStem,sourceLocalYearStemSame:localStemSame,
    sourceLunarIsLeap:record.lunarIsLeapMonth===true,
    sourceNames:{...position},
    sourceRawIztroNames:{...rawPosition},
    namedSourceFormulaReproduced:true,
    rawIztroToSourcePlacementReproduced:true,
    sourceFuxunPostprocessingReproduced:true,
    localTrietSameTwoBranches:trietGeometry,
    localTuanSameTwoBranches:tuanGeometry,
    localGeometryAuditStatus:localGeometry.status,
    nameEquivalenceVerified:false,sourceCriterionVerified:false}));
  }catch(err){
   failures.push(Object.freeze({...context,error:String(err&&err.message||err)}));
  }
 }
 const report={
  schema:'thiendo-r27-runtime-iztro-parity-report-v1',
  sourceCommit:SOURCE_COMMIT,iztroVersion:PINNED_IZTRO,
  sourceRunExecuted:true,syntheticCasesOnly:true,caseCount:fixture.cases.length,
  sourceConsistent:results.length,failures:failures.length,
  sourceYearStemLocalSame:results.filter(x=>x.sourceLocalYearStemSame).length,
  triGeometryMatches:results.filter(x=>x.localTrietSameTwoBranches===true).length,
  tuanGeometryMatches:results.filter(x=>x.localTuanSameTwoBranches===true).length,
  namedPlacementEquivalenceVerified:false,
  sourceSchoolParityVerified:false,
  sourceCriterionVerified:false,
  disclaimer:DISCLAIMER,results,failedCases:failures
 };
 return report;
}
if(require.main===module){
 const sourceFile=process.argv[2];
 if(!sourceFile)throw new Error('Runtime probe JSON path is required');
 const matrix=JSON.parse(fs.readFileSync(path.join(__dirname,'../../tests/fixtures/tuvi-r27-iztro-cases.json'),'utf8'));
 const source=JSON.parse(fs.readFileSync(path.resolve(sourceFile),'utf8'));
 const report=evaluate(source,matrix);
 fs.writeFileSync('.r27-iztro-parity-report.json',JSON.stringify(report,null,2)+'\n');
 console.log('R27 genuine iztro/source probe: '+report.sourceConsistent+'/'+report.caseCount+
  ' consistent, '+report.failures+' errors; two-branch geometry alone is not star equivalence');
 if(report.failures>0)process.exitCode=1;
}
module.exports=Object.freeze({evaluate,validateObservationShape,requireSingle,
 SOURCE_COMMIT,PINNED_IZTRO,PROBE_SCHEMA,DISCLAIMER});
